const statusLabels={pending:"검토 대기",approved:"게시됨",changes:"수정 요청",rejected:"반려됨",reported:"신고"};
const stored=JSON.parse(localStorage.getItem("lookalike-admin-demo")||"null");
let items=Array.isArray(stored)?stored:seed,activeStatus="pending",selectedId=null;
const $=s=>document.querySelector(s),esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const save=()=>localStorage.setItem("lookalike-admin-demo",JSON.stringify(items));
function counts(){return Object.keys(statusLabels).reduce((a,k)=>(a[k]=items.filter(x=>x.status===k).length,a),{})}
function renderNav(){const c=counts();$("#statusNav").innerHTML=Object.entries(statusLabels).map(([key,label])=>`<button class="nav-button ${key===activeStatus?"active":""}" type="button" data-status="${key}"><span data-short="${label.slice(0,2)}">${label}</span><span>${c[key]||0}</span></button>`).join("");document.querySelectorAll("[data-status]").forEach(b=>b.onclick=()=>{activeStatus=b.dataset.status;selectedId=null;render()})}
function filtered(){const q=$("#searchInput").value.trim().toLowerCase(),category=$("#categoryFilter").value,risk=$("#riskFilter").value,sort=$("#sortSelect").value;let list=items.filter(x=>x.status===activeStatus&&(!q||(x.nickname+x.intro+x.match).toLowerCase().includes(q))&&(category==="all"||x.category===category)&&(risk==="all"||x.risk===risk));const weight={주의:3,보통:2,낮음:1};return list.sort((a,b)=>sort==="newest"?a.stamp-b.stamp:sort==="risk"?weight[b.risk]-weight[a.risk]:b.stamp-a.stamp)}
function renderQueue(){const list=filtered();$("#queueTitle").textContent=statusLabels[activeStatus];$("#queueCount").textContent=`${list.length}개의 제출물`;$("#emptyState").hidden=!!list.length;if(list.length&&!list.some(x=>x.id===selectedId))selectedId=list[0].id;$("#queueList").innerHTML=list.map(x=>`<button class="queue-item ${x.id===selectedId?"selected":""}" type="button" data-id="${x.id}"><span class="submission"><img src="${esc(x.photo)}" alt=""><span><b>${esc(x.nickname)}</b><small>${esc(x.time)} · ${esc(x.match)} ${x.score}%</small></span></span><span class="category">${esc(x.category)}</span><span class="risk" data-risk="${x.risk}">${x.risk}</span></button>`).join("");document.querySelectorAll("[data-id]").forEach(b=>b.onclick=()=>{selectedId=b.dataset.id;renderQueue();renderReview()})}
function renderReview(){const x=items.find(i=>i.id===selectedId&&i.status===activeStatus);if(!x){$("#reviewPanel").innerHTML='<div class="review-empty"><b>검토할 제출물을 선택해 주세요</b><span>왼쪽 목록에서 항목을 선택하면 상세 정보가 열립니다.</span></div>';return}const locked=x.status!=="pending";$("#reviewPanel").innerHTML=`<header class="review-header"><div><h2>제출 상세 정보</h2><p>${x.id} · ${esc(x.time)} 제출</p></div><span class="status-mark">${statusLabels[x.status]}</span></header><div class="review-body"><div class="content-stack"><section class="media-compare"><div class="media-block"><h3>사용자 사진</h3><img src="${esc(x.photo)}" alt="${esc(x.nickname)} 제출 사진"></div><div class="arrow" aria-hidden="true">→</div><div class="media-block"><h3>닮은꼴 결과</h3><div class="match-card"><img src="${esc(x.matchPhoto)}" alt="${esc(x.match)} 기준 사진"><div class="match-meta"><b>${esc(x.match)}</b><strong>${x.score}%</strong></div></div></div></section><section class="section-box"><h3>소개글</h3><p class="intro">${esc(x.intro)}</p></section><section class="section-box"><h3>동의 및 공개 범위</h3><div class="check-list"><div class="check">본인 사진 게시 및 서비스 내 공개 동의</div><div class="check">초상권·저작권 안내 확인</div><div class="check">언제든 게시 중단을 요청할 수 있음</div></div></section><section class="section-box"><h3>관리자 메모</h3><textarea class="note" id="moderatorNote" maxlength="500" placeholder="판단 근거 또는 수정 요청 내용을 입력하세요.">${esc(x.note||"")}</textarea></section></div><div class="safety-stack"><section class="section-box"><h3>자동 안전성 검사</h3><div class="check-list">${x.checks.map(c=>`<div class="check ${c[2]==="ok"?"":c[2]}"><span>${esc(c[0])}</span><b>${esc(c[1])}</b></div>`).join("")}</div></section><section class="section-box"><h3>운영 체크리스트</h3><div class="check-list"><label class="check"><span>소개글에 연락처·계정·주소 없음</span></label><label class="check"><span>사진 속 제3자 동의 또는 가림 확인</span></label><label class="check"><span>비방·혐오·성적 표현 없음</span></label><label class="check"><span>결과를 사실·신원 확인처럼 표현하지 않음</span></label></div></section><section class="section-box"><h3>검토 이력</h3><div class="history">${x.history.map(h=>`<div><b>${esc(h[0])}</b><span>${esc(h[1])}</span></div>`).join("")}</div></section></div></div><footer class="actionbar"><button class="reject" type="button" data-action="rejected" ${locked?"disabled":""}>반려</button><button class="changes" type="button" data-action="changes" ${locked?"disabled":""}>수정 요청</button><button class="approve" type="button" data-action="approved" ${locked?"disabled":""}>승인 후 게시</button></footer>`;const note=$("#moderatorNote");if(note)note.oninput=()=>{x.note=note.value;save()};document.querySelectorAll("[data-action]").forEach(b=>b.onclick=()=>moderate(x,b.dataset.action))}
function moderate(item,status){if(status!=="approved"&&!($("#moderatorNote")?.value.trim())){showToast("반려 또는 수정 요청 사유를 메모에 입력해 주세요.");$("#moderatorNote")?.focus();return}item.status=status;item.history.push([statusLabels[status],`관리자 · 방금`]);save();selectedId=null;showToast(status==="approved"?"승인되어 공개 대기열로 이동했습니다.":`${statusLabels[status]} 상태로 이동했습니다.`);render()}
function showToast(text){const t=$("#toast");t.textContent=text;t.classList.add("show");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove("show"),2600)}
function renderSummary(){const c=counts();$("#todayApproved").textContent=c.approved;$("#todayRejected").textContent=c.rejected;$("#todayChanges").textContent=c.changes}
function render(){renderNav();renderSummary();renderQueue();renderReview()}
["searchInput","categoryFilter","riskFilter","sortSelect"].forEach(id=>$("#"+id).addEventListener(id==="searchInput"?"input":"change",()=>{selectedId=null;renderQueue();renderReview()}));$("#resetFilters").onclick=()=>{$("#searchInput").value="";$("#categoryFilter").value="all";$("#riskFilter").value="all";selectedId=null;renderQueue();renderReview()};render();
